use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut sieve: Vec<bool> = []
    let mut counts: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut i = 0
    while i <= 200000 {
        sieve.push(true)
        counts.push(0)
        largest.push(-1)
        i += 1
    }
    let mut p = 2
    while p <= 200000 {
        if sieve[p] {
            let mut m = p * 2
            while m <= 200000 {
                sieve[m] = false
                m += p
            }
        }
        p += 1
    }
    let mut c = 0
    let mut last = -1
    let mut k = 0
    while k <= 200000 {
        if k >= 2 && sieve[k] {
            c += 1
            last = k
        }
        counts[k] = c
        largest[k] = last
        k += 1
    }
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 {
            continue
        }
        if first {
            first = false
            continue
        }
        let n: int = t.parse().unwrap_or(0)
        if largest[n] < 0 {
            println("0 none")
        } else {
            println("${counts[n]} ${largest[n]}")
        }
    }
}

